import 'dart:async';
import 'dart:math' as math;

/// An item in stock.
class Item {
  final String name;
  final int count;

  const Item(this.name, [this.count = 0]);

  Item copyWith({int? count}) => Item(name, count ?? this.count);

  @override
  String toString() => 'Item($name, $count)';
}

enum Level { low, high }

mixin Logging {
  void log(String message) => print('[log] $message');
}

class Store with Logging {
  final _items = <String, Item>{};
  late final int limit;

  Store(this.limit);

  void add(Item item) {
    if (_items.length >= limit) {
      throw StateError('full');
    }
    _items[item.name] = item;
    log('added ${item.name}');
  }

  int get total => _items.values.fold(0, (sum, i) => sum + i.count);

  Level levelOf(String name) {
    final count = _items[name]?.count ?? 0;
    return count > 100 ? Level.high : Level.low;
  }
}

Future<void> main() async {
  final store = Store(4)..add(const Item('bolt', 120));
  for (var i = 0; i < 3; i++) {
    store.add(Item('item$i', math.max(i, 1)));
  }
  await Future.delayed(Duration.zero);
  print('total=${store.total}');
}

import 'dart:math';

int largest(List<int> values) {
  var best = values.first;
  for (final v in values) {
    best = max(best, v);
  }
  return best;
}

void main() {
  final data = [4, 9, 2];
  print(largest(data));
}
